-- TPC-DS Test_Query Query 403
-- Based on: query53.tpl (medium)
-- Variation: 30

 select  * from (select i_manufact_id, sum(ss_sales_price) sum_sales, avg(sum(ss_sales_price)) over (partition by i_manufact_id) avg_quarterly_sales from item, store_sales, date_dim, store where ss_item_sk = i_item_sk and ss_sold_date_sk = d_date_sk and ss_store_sk = s_store_sk and d_month_seq in (61,4+2,27+2,90+5,43+3,62+6,36+6,72+9,17+8,5+8,54+12,27+8) and ((i_category in ('Books','Children','Electronics') and i_class in ('personal','portable','reference','self-help') and i_brand in ('scholaramalgamalg #15','scholaramalgamalg #6', 'exportiunivamalg #8','scholaramalgamalg #8')) or(i_category in ('Women','Music','Men') and i_class in ('accessories','classical','fragrances','pants') and i_brand in ('amalgimporto #1','edu packscholar #3','exportiimporto #3', 'importoamalg #3'))) group by i_manufact_id, d_qoy ) tmp1 where case when avg_quarterly_sales > 1 then abs (sum_sales - avg_quarterly_sales)/ avg_quarterly_sales else null end > 0.2 order by avg_quarterly_sales, sum_sales, i_manufact_id limit 97;
